/**
 * Photography registry. Files are generated by scripts/build-images.sh.
 * Current photos are licensed stock (Unsplash Licence) used as placeholders
 * for mood and context only — they do not depict 8PAHAR projects. Replace
 * with commissioned project photography when available (see CREDITS.md).
 */
export interface ImageSource {
  name: string;
  widths: number[];
  /** Intrinsic aspect ratio (width / height) used to reserve layout space. */
  width: number;
  height: number;
}

const img = (name: string, widths: number[], width: number, height: number): ImageSource => ({ name, widths, width, height });

export const images = {
  'hero-residence': img('hero-residence', [640, 960, 1280, 1800], 1800, 1200),
  'cctv-pole': img('cctv-pole', [480, 800, 1200], 1200, 800),
  'monitoring-room': img('monitoring-room', [640, 960, 1400], 1400, 933),
  residential: img('residential', [480, 800, 1200], 1200, 1006),
  commercial: img('commercial', [480, 800, 1200], 1200, 800),
  industrial: img('industrial', [480, 800, 1200], 1200, 800),
  construction: img('construction', [480, 800, 1200], 1200, 800),
  assessment: img('assessment', [480, 800, 1200], 1200, 512),
  technician: img('technician', [480, 800, 1200], 1200, 801),
} as const;

export type ImageName = keyof typeof images;

/** Rendered width of the hero photograph — shared by the <img> and its preload hint. */
export const heroImageSizes = '(min-width: 1024px) 46vw, 100vw';
